'use strict';const {config:C,sprites,place}=require('../public/slime-shared.js');
class SlimeSystem{
 constructor(world){this.world=world;this.entities=new Map();this.nextId=1;this.aiEnabled=true;this.testingOriginal=null;this.autoEnabled=true;this.spawnRng=world.spawnRng||Math.random;this.scheduleAuto();this.metrics={spawned:0,killed:0,damage:0,attacks:0,attackHits:0,hops:0};}
 list(){return [...this.entities.values()];}get(id){return this.entities.get(id);}
 spawn(x,y){if(this.entities.size>=C.maxActive)throw Error('Límite de '+C.maxActive+' slimes activos');const where=place(x,y,this.world.scene.terrain,this.world.bodies(),this.world.scene.radius);if(!where.valid)throw Error(where.message);let id;do{id='slime-'+this.nextId++;}while(this.world.get(id));const e={id,name:'Slime',kind:'slime',radius:C.radius,leg:C.leg,canCollectCoins:false,...where,active:true,vx:0,vy:0,dir:1,intent:0,grounded:false,supportId:null,action:null,grabbedBy:null,phase:0,cooldownUntil:0,reactionUntil:0,pushUntil:0,nextThink:0,invalidLinkTime:0,ladderIntent:0,ladderPass:false,friction:1,hp:C.hp,state:'falling',target:null,targetAt:0,nextHop:this.world.time+.35,nextAttack:0,attack:null,hurtUntil:0,immuneUntil:0,hitIds:new Set()};delete e.valid;const support=this.world.scene.terrain.find(q=>Math.abs(e.y+e.radius-q.y)<.01&&e.x>=q.x&&e.x<=q.x+q.w);if(support){e.grounded=true;e.supportId=support.id;e.state='idle';}this.entities.set(id,e);this.metrics.spawned++;return e;}
 kill(e){if(!e?.active)return false;e.active=false;e.state='dead';e.attack=null;e.target=null;for(const p of this.world.bodies())if(p.action?.target===e.id)this.world.release(p);this.world.release(e);e.grabbedBy=null;e.hitIds.clear();this.entities.delete(e.id);this.metrics.killed++;return true;}
 clear(){for(const e of this.list())this.kill(e);}
 reset(){this.clear();this.scheduleAuto();if(this.testingOriginal!==null){this.world.equipment.attack=null;this.world.equipment.pending=null;this.world.equipment.item=this.testingOriginal;this.testingOriginal=null;}}
 randomSpawn(){return Math.max(0,Math.min(1-Number.EPSILON,this.spawnRng()));}
 scheduleAuto(){this.nextAuto=this.world.time+C.autoMinDelay+this.randomSpawn()*(C.autoMaxDelay-C.autoMinDelay);}
 setAuto(on){this.autoEnabled=on;if(on)this.scheduleAuto();}
 updateAuto(){if(!this.autoEnabled||this.world.time+1e-9<this.nextAuto)return;this.scheduleAuto();if(this.entities.size>=C.maxActive)return;const surfaces=this.world.scene.terrain;for(let attempt=0;attempt<32;attempt++){const q=surfaces[Math.floor(this.randomSpawn()*surfaces.length)],margin=C.radius+8,x=q.x+margin+this.randomSpawn()*(q.w-margin*2);try{this.spawn(x,q.y);return;}catch{/* Ocupación: intentar otro punto; nunca acumular apariciones. */}}}
 setAI(on){this.aiEnabled=on;for(const e of this.list()){e.attack=null;e.nextHop=this.world.time+.35;e.targetAt=0;}}
 reachable(e,p){if(!p.active||p.kind==='slime')return false;const feet=p.y+this.world.radiusOf(p)+this.world.legOf(p),ours=e.y+C.radius,max=C.hopSpeed*C.hopSpeed/(2*this.world.config.gravity);return feet>=ours-max-4;}
 target(e){const now=this.world.time;if(now<e.targetAt){const prior=this.world.get(e.target);if(prior&&this.reachable(e,prior))return prior;if(!e.target)return null;}e.targetAt=now+C.targetInterval;const candidates=this.world.players.filter(p=>this.reachable(e,p)).sort((a,b)=>Math.hypot(a.x-e.x,a.y-e.y)-Math.hypot(b.x-e.x,b.y-e.y));let selected=candidates[0],prior=this.world.get(e.target);if(selected&&prior&&this.reachable(e,prior)&&Math.hypot(prior.x-e.x,prior.y-e.y)<=Math.hypot(selected.x-e.x,selected.y-e.y)+C.targetHysteresis)selected=prior;e.target=selected?.id||null;return selected;}
 state(e){const now=this.world.time;if(!e.active)return 'dead';if(e.grabbedBy)return 'grabbed';if(now<e.hurtUntil)return 'hurt';if(e.attack)return now<e.attack.activeAt?'prepare_attack':'attacking';if(!e.grounded)return e.vy<0?'jumping':'falling';if(this.aiEnabled&&now>=e.nextHop-C.prepareTime)return 'prepare_jump';return this.aiEnabled&&e.target?'chasing':'idle';}
 think(e){const w=this.world,now=w.time;e.intent=0;e.friction=e.grounded?(now<e.reactionUntil?3.2:14):.7;if(e.grabbedBy){e.attack=null;e.nextHop=now+.35;e.state='grabbed';return;}if(now<e.hurtUntil){e.state='hurt';return;}if(!this.aiEnabled){e.attack=null;e.state=this.state(e);return;}
 const target=this.target(e);if(target&&Math.abs(target.x-e.x)>8)e.dir=Math.sign(target.x-e.x);
 if(e.attack){e.friction=3.2;if(now>=e.attack.until){e.attack=null;e.nextAttack=now+C.attackCooldown;}else if(now>=e.attack.activeAt&&!e.attack.launched){e.attack.launched=true;e.vx=e.attack.dir*C.attackSpeed;}e.state=this.state(e);return;}
 if(e.grounded&&target&&now>=e.nextAttack&&Math.hypot(target.x-e.x,target.y-e.y)<=C.radius+w.radiusOf(target)+C.attackReach){e.attack={id:++w.serial,dir:e.dir,activeAt:now+C.attackPrepare,until:now+C.attackPrepare+C.attackDuration,launched:false,hits:new Set()};this.metrics.attacks++;e.state='prepare_attack';return;}
 if(e.grounded&&now>=e.nextHop){const ahead=e.x+e.dir*C.hopHorizontal*(2*C.hopSpeed/w.config.gravity);const safe=w.scene.terrain.some(q=>ahead>=q.x+C.radius&&ahead<=q.x+q.w-C.radius&&q.y>=e.y+C.radius-60);if(!safe&&w.rng()>.1)e.dir=-e.dir;e.vx=e.dir*C.hopHorizontal;e.vy=-C.hopSpeed;e.grounded=false;e.supportId=null;e.nextHop=now+C.hopIntervalMin+w.rng()*(C.hopIntervalMax-C.hopIntervalMin);this.metrics.hops++;}e.state=this.state(e);
 }
 // Reutiliza j=-velocidadRelativa/sumaDeMovilidades del motor: nunca añade otro impulso.
 contactScale(a,b){for(const [e,p]of [[a,b],[b,a]]){if(e.kind!=='slime'||p.kind==='slime'||!p.active||e.grabbedBy||this.world.time<e.hurtUntil||!e.attack?.launched||this.world.time>=e.attack.until||e.attack.dir*(p.x-e.x)<=0)continue;if(e.attack.hits.has(p.id))return 0;e.attack.hits.add(p.id);p.slimePushUntil=this.world.time+this.world.config.reactionDuration;this.world.react(p,e.attack.id);this.metrics.attackHits++;return C.attackPushRatio;}return 1;}

 damage(e,{id,kind,source}){if(!e?.active||!['sword','spear','projectile'].includes(kind)||!Number.isSafeInteger(id))return false;const key=kind+':'+id;if(e.hitIds.has(key))return false;e.hitIds.add(key);if(e.hitIds.size>64)e.hitIds.delete(e.hitIds.values().next().value);if(this.world.time<e.immuneUntil)return false;e.hp--;e.attack=null;e.immuneUntil=this.world.time+C.immunity;e.hurtUntil=this.world.time+C.hurtDuration;e.nextHop=e.hurtUntil+.3;e.state='hurt';this.metrics.damage++;if(e.hp<=0)this.kill(e);return true;}
 testStrike(){const w=this.world,p=w.get('you'),eq=w.equipment;if(w.paused||!p?.active||p.action||eq.attack||w.extras.flag)return false;this.testingOriginal=eq.item;if(!eq.equip('sword')||!eq.use()){this.testingOriginal=null;return false;}eq.pending=this.testingOriginal;return true;}
 afterStep(){if(this.testingOriginal!==null&&!this.world.equipment.attack&&this.world.equipment.pending===null)this.testingOriginal=null;}
 snapshot(){return this.list().map(e=>({id:e.id,x:e.x,y:e.y,vx:e.vx,vy:e.vy,dir:e.dir,radius:e.radius,active:e.active,hp:e.hp,state:this.state(e),target:e.target,grabbedBy:e.grabbedBy,sprite:this.state(e)==='hurt'?'hurt':this.state(e)==='attacking'?'attack':['jumping','falling'].includes(this.state(e))?'jump':'normal'}));}
}
module.exports={SlimeSystem,C};
